window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["ai-navigator"]={html:"<div class=\"own-ai-navigator\">\n  <!-- ── TOPBAR ──────────────────────────────────────────────────────── -->\n  <header class=\"an-topbar\">\n    <a class=\"an-brand\" href=\"#an-overview\" aria-label=\"Northwind home\">\n      <span class=\"an-logo\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\">\n          <path d=\"M3 20 12 3l9 17\" stroke=\"var(--an-lime)\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/>\n          <path d=\"M7.5 14h9\" stroke=\"#E8434A\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n        </svg>\n      </span>\n      <span class=\"an-brand-text\">\n        <span class=\"an-brand-name\">Northwind</span>\n        <span class=\"an-brand-sub\">OPS · CONSOLE</span>\n      </span>\n    </a>\n\n    <nav class=\"an-topnav\" aria-label=\"Primary\">\n      <a href=\"#an-overview\" class=\"an-topnav-link on\">Home</a>\n      <a href=\"#an-overview\" class=\"an-topnav-link\">My Dashboard</a>\n      <a href=\"#an-throughput\" class=\"an-topnav-link\">Cockpit</a>\n      <a href=\"#an-regions\" class=\"an-topnav-link\">Reports</a>\n    </nav>\n\n    <div class=\"an-tools\">\n      <label class=\"an-search\">\n        <span class=\"an-sr\">Search regions, metrics, sites</span>\n        <svg viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" aria-hidden=\"true\">\n          <circle cx=\"11\" cy=\"11\" r=\"7\" stroke=\"currentColor\" stroke-width=\"1.8\"/>\n          <path d=\"m20 20-4-4\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/>\n        </svg>\n        <input type=\"search\" placeholder=\"Search regions, metrics, sites\" autocomplete=\"off\">\n        <kbd class=\"an-kbd\">⌘K</kbd>\n      </label>\n      <div class=\"an-icon-tray\" role=\"group\" aria-label=\"Tools\">\n        <button type=\"button\" class=\"an-icon\" aria-label=\"Alerts\" data-an-tip=\"Alerts\">\n          <svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" aria-hidden=\"true\">\n            <path d=\"M6 16.5V11a6 6 0 1 1 12 0v5.5l1.5 1.5H4.5L6 16.5z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/>\n            <path d=\"M10 20.5a2 2 0 0 0 4 0\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/>\n          </svg>\n          <span class=\"an-dot\" aria-hidden=\"true\"></span>\n        </button>\n        <button type=\"button\" class=\"an-icon\" aria-label=\"Schedules\" data-an-tip=\"Schedules\">\n          <svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" aria-hidden=\"true\">\n            <rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\" stroke=\"currentColor\" stroke-width=\"1.7\"/>\n            <path d=\"M3 9h18M8 3v4M16 3v4\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/>\n          </svg>\n        </button>\n        <span class=\"an-tray-div\" aria-hidden=\"true\"></span>\n        <button type=\"button\" class=\"an-icon\" aria-label=\"Toggle theme\" data-an-theme>\n          <svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" aria-hidden=\"true\">\n            <path d=\"M12 3a9 9 0 1 0 9 9 7 7 0 0 1-9-9z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/>\n          </svg>\n        </button>\n      </div>\n      <button type=\"button\" class=\"an-user\" aria-label=\"Account\">\n        <span class=\"an-avatar\" aria-hidden=\"true\">RK</span>\n        <span class=\"an-user-info\">\n          <span class=\"an-user-name\">Rina Kalaw</span>\n          <span class=\"an-user-role\">Operations Lead</span>\n        </span>\n      </button>\n    </div>\n  </header>\n\n  <div class=\"an-shell\">\n    <!-- ── PAGE ───────────────────────────────────────────────────────── -->\n    <main class=\"an-main\">\n      <!-- Greeting -->\n      <div class=\"an-pagehead\">\n        <div>\n          <div class=\"an-greeting-sub\">Q3 2026<span class=\"an-sep\">|</span>All regions reporting</div>\n          <h1 class=\"an-greeting\">Operations Console</h1>\n        </div>\n        <div class=\"an-pagehead-actions\">\n          <span class=\"an-pill an-pill-hot\">Live data</span>\n          <button type=\"button\" class=\"an-btn an-btn-primary\">Export board</button>\n        </div>\n      </div>\n\n      <!-- Section nav (the app's segmented control, driving in-page scroll) -->\n      <nav class=\"an-tabs\" aria-label=\"Console sections\">\n        <a class=\"an-tab on\" href=\"#an-overview\" data-an-tab=\"an-overview\" aria-current=\"true\">Overview</a>\n        <a class=\"an-tab\" href=\"#an-throughput\" data-an-tab=\"an-throughput\">Throughput</a>\n        <a class=\"an-tab\" href=\"#an-regions\" data-an-tab=\"an-regions\">Regions</a>\n        <a class=\"an-tab\" href=\"#an-pricing\" data-an-tab=\"an-pricing\">Pricing</a>\n      </nav>\n\n      <!-- Overview -->\n      <section class=\"an-panel\" id=\"an-overview\" data-an-panel=\"an-overview\" aria-label=\"Overview\">\n        <div class=\"an-section-head\">\n          <span class=\"an-eyebrow\">01 · Network</span>\n          <h2 class=\"an-section-title\">Today at a glance</h2>\n        </div>\n        <div class=\"an-kpi-rail\">\n          <div class=\"an-kpi-compact\">\n            <div class=\"an-kpi-label\">Units / day</div>\n            <div class=\"an-kpi-value\" data-an-count=\"184000\" data-an-fmt=\"k\">0</div>\n            <div class=\"an-kpi-sub\"><span class=\"an-delta up\">▲ 12.4%</span> vs Q2</div>\n          </div>\n          <div class=\"an-kpi-compact\">\n            <div class=\"an-kpi-label\">Regions live</div>\n            <div class=\"an-kpi-value\">6<span class=\"an-kpi-of\">/6</span></div>\n            <div class=\"an-kpi-sub\">single metric layer</div>\n          </div>\n          <div class=\"an-kpi-compact\">\n            <div class=\"an-kpi-label\">On-time roll-up</div>\n            <div class=\"an-kpi-value\" data-an-count=\"99.2\" data-an-fmt=\"pct\">0</div>\n            <div class=\"an-kpi-sub\">before 06:00 local</div>\n          </div>\n          <div class=\"an-kpi-compact an-tone-warn\">\n            <div class=\"an-kpi-label\">Open alerts</div>\n            <div class=\"an-kpi-value\">2</div>\n            <div class=\"an-kpi-sub\"><span class=\"an-status-dot warn\" aria-hidden=\"true\"></span>1 warn · 1 crit</div>\n          </div>\n        </div>\n\n        <div class=\"an-grid-2\">\n          <!-- Hero briefing card with crawling lime ring on hover -->\n          <article class=\"an-focus-card an-briefing-card\">\n            <div class=\"an-brief-head\">\n              <span class=\"an-card-head\">Morning brief</span>\n              <span class=\"an-pill\">06:00 local</span>\n            </div>\n            <h3 class=\"an-brief-title\">APAC carried the network — and MEA still lags</h3>\n            <p class=\"an-brief-body\">Network throughput came in at <strong>184K units/day</strong>, <strong>12.4%</strong> ahead of Q2. Five of six regions beat plan; <em>MEA remains 10% behind</em> and needs the source fix tracked under D-2 before the v4.1 freeze.</p>\n            <div class=\"an-brief-actions\">\n              <button type=\"button\" class=\"an-chip\">Open APAC board</button>\n              <button type=\"button\" class=\"an-chip\">Review MEA</button>\n              <button type=\"button\" class=\"an-chip\">Draft the brief</button>\n            </div>\n          </article>\n\n          <div class=\"an-stack\">\n            <div class=\"an-focus-card\">\n              <div class=\"an-card-head-row\"><span class=\"an-card-head\">Last roll-up</span><span class=\"an-mono an-muted\">05:41 local</span></div>\n              <div class=\"an-session-row\">\n                <span class=\"an-session-name\">Network snapshot · 6 regions</span>\n                <span class=\"an-pill an-pill-ok\">reconciled</span>\n              </div>\n              <div class=\"an-mono an-muted an-small\">All six regions landed before the 06:00 SLA.</div>\n            </div>\n            <div class=\"an-focus-card\">\n              <div class=\"an-card-head-row\"><span class=\"an-card-head\">Parked regions</span><span class=\"an-mono an-muted\">2 flagged</span></div>\n              <div class=\"an-parked-row\"><span>MEA — source timestamps</span><button type=\"button\" class=\"an-resume\">RESUME →</button></div>\n              <div class=\"an-parked-row\"><span>EMEA — seasonal history</span><button type=\"button\" class=\"an-resume\">RESUME →</button></div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"an-alert-grid\">\n          <div class=\"an-alert-card warn\">\n            <span class=\"an-alert-title\"><span class=\"an-status-dot warn\" aria-hidden=\"true\"></span>Watch — EMEA</span>\n            <p>Throughput 5.0% behind plan. No source issue; seasonal dip is within tolerance.</p>\n          </div>\n          <div class=\"an-alert-card crit\">\n            <span class=\"an-alert-title\"><span class=\"an-status-dot crit\" aria-hidden=\"true\"></span>Critical — MEA</span>\n            <p>Two sites report zero inventory aging: missing source timestamp. Blocks the v4.1 aging board.</p>\n          </div>\n          <div class=\"an-alert-card ok\">\n            <span class=\"an-alert-title\"><span class=\"an-status-dot ok\" aria-hidden=\"true\"></span>Healthy — APAC</span>\n            <p>Best region this quarter, +15.7% to plan. No action needed.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- Throughput -->\n      <section class=\"an-panel\" id=\"an-throughput\" data-an-panel=\"an-throughput\" aria-label=\"Throughput\">\n        <div class=\"an-section-head\">\n          <span class=\"an-eyebrow\">02 · Throughput</span>\n          <h2 class=\"an-section-title\">Plan vs. actual by region</h2>\n        </div>\n        <div class=\"an-focus-card\">\n          <div class=\"an-card-head-row\">\n            <span class=\"an-card-head\">Regional throughput</span>\n            <span class=\"an-mono an-muted\">13 weeks · network total 184K/day</span>\n          </div>\n          <div class=\"an-table-wrap\">\n            <table class=\"an-table\">\n              <thead>\n                <tr><th>Region</th><th class=\"an-num\">Plan</th><th class=\"an-num\">Actual</th><th class=\"an-num\">Variance</th><th>Status</th></tr>\n              </thead>\n              <tbody>\n                <tr><td>APAC</td><td class=\"an-num\">42.0K</td><td class=\"an-num\">48.6K</td><td class=\"an-num an-crit-accent\">+15.7%</td><td><span class=\"an-pill an-pill-ok\">ahead</span></td></tr>\n                <tr><td>North America</td><td class=\"an-num\">56.0K</td><td class=\"an-num\">59.2K</td><td class=\"an-num an-crit-accent\">+5.7%</td><td><span class=\"an-pill an-pill-ok\">ahead</span></td></tr>\n                <tr><td>EMEA</td><td class=\"an-num\">38.0K</td><td class=\"an-num\">36.1K</td><td class=\"an-num\">−5.0%</td><td><span class=\"an-pill an-pill-warn\">watch</span></td></tr>\n                <tr><td>LATAM</td><td class=\"an-num\">21.0K</td><td class=\"an-num\">22.4K</td><td class=\"an-num an-crit-accent\">+6.7%</td><td><span class=\"an-pill an-pill-ok\">ahead</span></td></tr>\n                <tr><td>MEA</td><td class=\"an-num\">12.0K</td><td class=\"an-num\">10.8K</td><td class=\"an-num\">−10.0%</td><td><span class=\"an-pill an-pill-crit\">behind</span></td></tr>\n                <tr><td>India</td><td class=\"an-num\">15.0K</td><td class=\"an-num\">16.9K</td><td class=\"an-num an-crit-accent\">+12.7%</td><td><span class=\"an-pill an-pill-ok\">ahead</span></td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n        <div class=\"an-grid-2\">\n          <div class=\"an-focus-card\">\n            <div class=\"an-card-head\">13-week trend</div>\n            <svg class=\"an-chart\" viewBox=\"0 0 520 160\" role=\"img\" aria-label=\"Network throughput trend, rising over 13 weeks\">\n              <defs>\n                <linearGradient id=\"an-fill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <stop offset=\"0%\" stop-color=\"var(--an-lime)\" stop-opacity=\"0.35\"/>\n                  <stop offset=\"100%\" stop-color=\"var(--an-lime)\" stop-opacity=\"0\"/>\n                </linearGradient>\n              </defs>\n              <path d=\"M0,120 L43,112 L86,116 L130,100 L173,104 L216,88 L260,92 L303,74 L346,78 L390,60 L433,54 L476,44 L520,30 L520,160 L0,160 Z\" fill=\"url(#an-fill)\"/>\n              <path d=\"M0,120 L43,112 L86,116 L130,100 L173,104 L216,88 L260,92 L303,74 L346,78 L390,60 L433,54 L476,44 L520,30\" fill=\"none\" stroke=\"var(--an-lime)\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/>\n              <circle cx=\"520\" cy=\"30\" r=\"4\" fill=\"var(--an-lime)\"/>\n            </svg>\n            <div class=\"an-chart-x\"><span>W1</span><span>W5</span><span>W9</span><span>W13</span></div>\n          </div>\n          <div class=\"an-focus-card\">\n            <div class=\"an-card-head\">Variance to plan</div>\n            <div class=\"an-bars\">\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">APAC</span><span class=\"an-bar\"><i class=\"up\" style=\"width:88%\"></i></span><span class=\"an-bar-val\">+15.7%</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">India</span><span class=\"an-bar\"><i class=\"up\" style=\"width:70%\"></i></span><span class=\"an-bar-val\">+12.7%</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">LATAM</span><span class=\"an-bar\"><i class=\"up\" style=\"width:44%\"></i></span><span class=\"an-bar-val\">+6.7%</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">N. America</span><span class=\"an-bar\"><i class=\"up\" style=\"width:38%\"></i></span><span class=\"an-bar-val\">+5.7%</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">EMEA</span><span class=\"an-bar\"><i class=\"down\" style=\"width:34%\"></i></span><span class=\"an-bar-val\">−5.0%</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">MEA</span><span class=\"an-bar\"><i class=\"down\" style=\"width:56%\"></i></span><span class=\"an-bar-val\">−10.0%</span></div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Regions -->\n      <section class=\"an-panel\" id=\"an-regions\" data-an-panel=\"an-regions\" aria-label=\"Regions\">\n        <div class=\"an-section-head\">\n          <span class=\"an-eyebrow\">03 · Regions</span>\n          <h2 class=\"an-section-title\">Sites and coverage</h2>\n        </div>\n        <div class=\"an-grid-2\">\n          <div class=\"an-focus-card\">\n            <div class=\"an-card-head\">Sites by region</div>\n            <div class=\"an-bars\">\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">N. America</span><span class=\"an-bar\"><i style=\"width:96%\"></i></span><span class=\"an-bar-val\">96</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">APAC</span><span class=\"an-bar\"><i style=\"width:78%\"></i></span><span class=\"an-bar-val\">78</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">EMEA</span><span class=\"an-bar\"><i style=\"width:64%\"></i></span><span class=\"an-bar-val\">64</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">LATAM</span><span class=\"an-bar\"><i style=\"width:41%\"></i></span><span class=\"an-bar-val\">41</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">India</span><span class=\"an-bar\"><i style=\"width:33%\"></i></span><span class=\"an-bar-val\">33</span></div>\n              <div class=\"an-bar-row\"><span class=\"an-bar-name\">MEA</span><span class=\"an-bar\"><i style=\"width:19%\"></i></span><span class=\"an-bar-val\">19</span></div>\n            </div>\n          </div>\n          <div class=\"an-focus-card\">\n            <div class=\"an-card-head\">Coverage</div>\n            <div class=\"an-hero-kpi\">\n              <div class=\"an-kpi-label\">Sites reporting</div>\n              <div class=\"an-kpi-value an-hero-val\">331<span class=\"an-kpi-of\">/331</span></div>\n              <div class=\"an-kpi-sub\">every active site in the nightly snapshot</div>\n            </div>\n            <div class=\"an-mini-list\">\n              <div><span class=\"an-status-dot ok\" aria-hidden=\"true\"></span><span>Full coverage</span><span class=\"an-mono an-muted\">100%</span></div>\n              <div><span class=\"an-status-dot warn\" aria-hidden=\"true\"></span><span>Partial aging data</span><span class=\"an-mono an-muted\">2 sites</span></div>\n              <div><span class=\"an-status-dot mute\" aria-hidden=\"true\"></span><span>No throughput history</span><span class=\"an-mono an-muted\">0 sites</span></div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Pricing -->\n      <section class=\"an-panel\" id=\"an-pricing\" data-an-panel=\"an-pricing\" aria-label=\"Pricing\">\n        <div class=\"an-section-head\">\n          <span class=\"an-eyebrow\">04 · Pricing</span>\n          <h2 class=\"an-section-title\">Operations tiers</h2>\n        </div>\n        <div class=\"an-focus-card\">\n          <div class=\"an-card-head-row\">\n            <span class=\"an-card-head\">Pricing tiers</span>\n            <span class=\"an-mono an-muted\">effective 2026-07-01</span>\n          </div>\n          <div class=\"an-tier-grid\">\n            <div class=\"an-tier\">\n              <div class=\"an-tier-name\">Standard</div>\n              <div class=\"an-tier-price\">$4.10<span class=\"an-tier-unit\">/seat</span></div>\n              <ul class=\"an-tier-list\"><li>Core throughput boards</li><li>Nightly roll-up</li><li>Threshold alerts</li></ul>\n            </div>\n            <div class=\"an-tier an-tier-hot\">\n              <span class=\"an-tier-badge\">Current</span>\n              <div class=\"an-tier-name\">Operations</div>\n              <div class=\"an-tier-price\">$7.40<span class=\"an-tier-unit\">/seat</span></div>\n              <ul class=\"an-tier-list\"><li>Everything in Standard</li><li>Anomaly detection</li><li>Region drill-down</li></ul>\n            </div>\n            <div class=\"an-tier\">\n              <div class=\"an-tier-name\">Enterprise</div>\n              <div class=\"an-tier-price\">$11.90<span class=\"an-tier-unit\">/seat</span></div>\n              <ul class=\"an-tier-list\"><li>Everything in Operations</li><li>Forecasting (v4.1)</li><li>Custom metric layer</li></ul>\n            </div>\n          </div>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <footer class=\"an-footer\">\n    <span class=\"an-mono\">NORTHWIND OPS CONSOLE · SAMPLE DATA — SHOWCASE ONLY</span>\n    <span class=\"an-mono an-muted\">Q3 2026 · RUN 2026-09-28</span>\n  </footer>\n</div>\n",css:"/* ══ AI NAVIGATOR — the dark-cosmic ops console, ported for showcase.html ═══\n   Ported from the AI Navigator app (app/globals.css + components/topbar.tsx +\n   components/tl/my-dashboard.tsx + session-history.tsx + commitment-table.tsx).\n   Near-black violet canvas, electric-lime accent, JetBrains Mono for every value\n   /label, Inter for prose. The fixed full-viewport ambient gradient becomes a root\n   background so it survives the showcase frame; production width media queries\n   become `@container frame` so Tablet (820) / Phone (390) reflow as they would. */\n\n.own-ai-navigator {\n  --an-lime: #D4FF00;\n  --an-lime-2: #E4FF4D;\n  --an-lime-soft: rgba(212, 255, 0, .15);\n  --an-lime-glow: rgba(212, 255, 0, .35);\n  --an-bg-0: #05060A;\n  --an-bg-1: #0A0C14;\n  --an-shell: #0E1120;\n  --an-card: #141728;\n  --an-card-hi: #1A1E34;\n  --an-text-0: #F4F6FB;\n  --an-text-1: #B6BCCC;\n  --an-text-2: #8A92A6;\n  --an-text-dark: #0A0C14;\n  --an-border: rgba(255, 255, 255, .06);\n  --an-border-hot: rgba(212, 255, 0, .3);\n  --an-red: #FF4D5E;\n  --an-amber: #FFB020;\n  --an-green: #38E1A1;\n  --an-info: #4FC3F7;\n  --an-ok-tint: rgba(56, 225, 161, .08);\n  --an-warn-tint: rgba(255, 176, 32, .10);\n  --an-crit-tint: rgba(255, 77, 94, .12);\n  --an-r-lg: 14px;\n  --an-r-md: 10px;\n  --an-r-sm: 8px;\n\n  --an-prose: 'Inter', system-ui, -apple-system, sans-serif;\n  --an-data: 'JetBrains Mono', ui-monospace, 'SF Mono', monospace;\n\n  position: relative;\n  isolation: isolate;\n  overflow-x: clip;\n  background: var(--an-bg-0);\n  background-image:\n    radial-gradient(ellipse at 15% 0%, rgba(212, 255, 0, .06), transparent 50%),\n    radial-gradient(ellipse at 85% 100%, rgba(139, 123, 255, .06), transparent 50%);\n  color: var(--an-text-0);\n  font-family: var(--an-prose);\n  font-size: 14px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n}\n\n.own-ai-navigator *,\n.own-ai-navigator *::before,\n.own-ai-navigator *::after { box-sizing: border-box; }\n\n.own-ai-navigator .an-sr {\n  position: absolute; width: 1px; height: 1px;\n  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;\n}\n.own-ai-navigator .an-mono { font-family: var(--an-data); }\n.own-ai-navigator .an-muted { color: var(--an-text-2); }\n.own-ai-navigator .an-small { font-size: 10.5px; }\n.own-ai-navigator .an-num { text-align: right; font-family: var(--an-data); white-space: nowrap; }\n.own-ai-navigator .an-crit-accent { color: var(--an-lime); }\n\n.own-ai-navigator :focus-visible {\n  outline: 2px solid var(--an-lime);\n  outline-offset: 2px;\n  border-radius: 6px;\n}\n\n/* ── Topbar ────────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-topbar {\n  position: sticky;\n  top: 68px; /* clears the 56px showcase toolbar */\n  z-index: 30;\n  display: flex;\n  align-items: center;\n  gap: 18px;\n  padding: 12px 24px;\n  background: rgba(10, 12, 20, .92);\n  border-bottom: 1px solid var(--an-border);\n  backdrop-filter: blur(12px);\n  -webkit-backdrop-filter: blur(12px);\n}\n.own-ai-navigator .an-brand {\n  display: flex; align-items: center; gap: 11px;\n  text-decoration: none; color: inherit; flex-shrink: 0; min-width: 0;\n}\n.own-ai-navigator .an-logo {\n  width: 38px; height: 38px; flex: none;\n  border-radius: 12px;\n  background: #0E2230;\n  box-shadow: 0 8px 22px -10px rgba(14, 34, 48, .6);\n  display: grid; place-items: center;\n}\n.own-ai-navigator .an-brand-name { display: block; font-size: 15px; font-weight: 700; color: var(--an-text-0); line-height: 1.1; }\n.own-ai-navigator .an-brand-sub {\n  display: block; margin-top: 3px;\n  font-family: var(--an-data); font-size: 9.5px; letter-spacing: 1.5px;\n  color: var(--an-text-2); text-transform: uppercase;\n}\n.own-ai-navigator .an-topnav { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.own-ai-navigator .an-topnav-link {\n  font-size: 13px; font-weight: 500;\n  color: var(--an-text-2);\n  text-decoration: none;\n  padding: 7px 12px;\n  border-radius: var(--an-r-md);\n  transition: color .15s, background .15s;\n  white-space: nowrap;\n}\n.own-ai-navigator .an-topnav-link:hover { color: var(--an-text-0); background: rgba(255, 255, 255, .03); }\n.own-ai-navigator .an-topnav-link.on { color: var(--an-text-0); background: rgba(255, 255, 255, .05); }\n\n.own-ai-navigator .an-tools { margin-left: auto; display: flex; align-items: center; gap: 10px; min-width: 0; }\n.own-ai-navigator .an-search {\n  display: flex; align-items: center; gap: 8px;\n  width: 300px; max-width: 34cqi;\n  padding: 8px 12px;\n  border: 1px solid var(--an-border);\n  background: rgba(255, 255, 255, .02);\n  border-radius: 12px;\n  color: var(--an-text-2);\n}\n.own-ai-navigator .an-search:focus-within { border-color: var(--an-border-hot); background: rgba(255, 255, 255, .04); }\n.own-ai-navigator .an-search svg { flex: none; }\n.own-ai-navigator .an-search input {\n  flex: 1; min-width: 0; appearance: none; border: 0; outline: 0;\n  background: transparent; color: var(--an-text-0);\n  font-family: var(--an-prose); font-size: 13px;\n}\n.own-ai-navigator .an-search input::placeholder { color: var(--an-text-2); }\n.own-ai-navigator .an-kbd {\n  font-family: var(--an-data); font-size: 10px; letter-spacing: .5px;\n  color: var(--an-text-2);\n  padding: 2px 6px; border: 1px solid var(--an-border); border-radius: 6px;\n  background: rgba(255, 255, 255, .02);\n}\n.own-ai-navigator .an-icon-tray {\n  display: flex; align-items: center; gap: 4px;\n  padding: 5px;\n  border-radius: 14px;\n  background: var(--an-bg-0);\n  border: 1px solid var(--an-border);\n  box-shadow: inset 0 2px 5px rgba(0, 0, 0, .45), inset 0 -1px 0 rgba(255, 255, 255, .04);\n}\n.own-ai-navigator .an-icon {\n  position: relative;\n  appearance: none; border: 1px solid transparent; background: transparent;\n  color: var(--an-text-1);\n  width: 34px; height: 34px; border-radius: 10px;\n  display: grid; place-items: center; cursor: pointer;\n  transition: color .15s, background .15s, border-color .15s;\n}\n.own-ai-navigator .an-icon:hover { color: var(--an-lime); border-color: var(--an-border-hot); background: var(--an-lime-soft); }\n.own-ai-navigator .an-dot {\n  position: absolute; top: 7px; right: 7px;\n  width: 7px; height: 7px; border-radius: 50%;\n  background: var(--an-red);\n  box-shadow: 0 0 6px rgba(255, 77, 94, .8);\n  border: 1.5px solid var(--an-bg-0);\n}\n.own-ai-navigator .an-tray-div { width: 1px; height: 20px; background: var(--an-border); margin: 0 3px; }\n.own-ai-navigator .an-user {\n  display: flex; align-items: center; gap: 9px;\n  padding: 5px 12px 5px 6px;\n  border: 1px solid var(--an-border);\n  background: rgba(255, 255, 255, .02);\n  border-radius: 999px;\n  color: var(--an-text-0); cursor: pointer;\n  font-family: inherit;\n}\n.own-ai-navigator .an-user:hover { border-color: var(--an-border-hot); background: var(--an-lime-soft); }\n.own-ai-navigator .an-avatar {\n  width: 30px; height: 30px; flex: none; border-radius: 50%;\n  background: linear-gradient(135deg, var(--an-lime), #7FB000);\n  color: var(--an-text-dark);\n  display: grid; place-items: center;\n  font-family: var(--an-data); font-weight: 700; font-size: 11px;\n}\n.own-ai-navigator .an-user-info { display: flex; flex-direction: column; line-height: 1.15; }\n.own-ai-navigator .an-user-name { font-size: 12.5px; font-weight: 600; }\n.own-ai-navigator .an-user-role { font-family: var(--an-data); font-size: 9px; letter-spacing: .06em; color: var(--an-text-2); text-transform: uppercase; margin-top: 2px; }\n\n/* ── Shell ──────────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-shell { position: relative; z-index: 1; }\n.own-ai-navigator .an-main {\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 24px 36px 40px;\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n\n/* ── Page head ─────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-pagehead {\n  display: flex; align-items: flex-end; justify-content: space-between;\n  gap: 20px; flex-wrap: wrap;\n}\n.own-ai-navigator .an-greeting-sub {\n  font-family: var(--an-data); font-size: 11px; text-transform: uppercase;\n  letter-spacing: 1.5px; color: var(--an-text-2); margin-bottom: 8px;\n}\n.own-ai-navigator .an-sep { margin: 0 10px; opacity: .4; }\n.own-ai-navigator .an-greeting { margin: 0; font-size: 28px; font-weight: 600; letter-spacing: -.02em; color: var(--an-text-0); }\n.own-ai-navigator .an-pagehead-actions { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }\n\n/* ── Pills / buttons / chips ────────────────────────────────────────────────── */\n.own-ai-navigator .an-pill {\n  font-family: var(--an-data); text-transform: uppercase; letter-spacing: 1.5px;\n  font-size: 10px; padding: 5px 12px; border-radius: 999px;\n  display: inline-flex; align-items: center; gap: 6px;\n  border: 1px solid var(--an-border); color: var(--an-text-1); background: var(--an-card);\n  white-space: nowrap;\n}\n.own-ai-navigator .an-pill-hot { border-color: var(--an-border-hot); background: var(--an-lime-soft); color: var(--an-lime); box-shadow: 0 0 24px var(--an-lime-glow); }\n.own-ai-navigator .an-pill-ok { color: var(--an-green); }\n.own-ai-navigator .an-pill-warn { color: var(--an-amber); }\n.own-ai-navigator .an-pill-crit { color: var(--an-red); }\n\n.own-ai-navigator .an-btn {\n  font-family: var(--an-prose); font-size: 13px; font-weight: 500;\n  padding: 8px 14px; border-radius: var(--an-r-md);\n  border: 1px solid var(--an-border); background: var(--an-card); color: var(--an-text-0);\n  cursor: pointer; display: inline-flex; align-items: center; gap: 8px;\n  transition: background .15s, border-color .15s;\n}\n.own-ai-navigator .an-btn:hover { background: var(--an-card-hi); border-color: rgba(255, 255, 255, .1); }\n.own-ai-navigator .an-btn-primary {\n  background: var(--an-lime); color: var(--an-text-dark);\n  border-color: var(--an-lime); font-weight: 600;\n  box-shadow: 0 0 24px var(--an-lime-glow);\n}\n.own-ai-navigator .an-btn-primary:hover { background: var(--an-lime-2); }\n\n.own-ai-navigator .an-chip {\n  font-family: var(--an-prose); font-size: 13px;\n  padding: 7px 12px; border-radius: 999px;\n  border: 1px solid var(--an-border); background: rgba(255, 255, 255, .04);\n  color: var(--an-text-1); cursor: pointer;\n  transition: border-color .15s, color .15s;\n}\n.own-ai-navigator .an-chip:hover { border-color: var(--an-border-hot); color: var(--an-text-0); }\n\n.own-ai-navigator .an-resume {\n  font-family: var(--an-data); font-size: 10px; letter-spacing: .04em;\n  color: var(--an-lime); background: none; border: 0; cursor: pointer; padding: 2px 0;\n  white-space: nowrap;\n}\n.own-ai-navigator .an-resume:hover { color: var(--an-lime-2); }\n\n/* ── Tabs ───────────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-tabs {\n  display: inline-flex;\n  border: 1px solid var(--an-border);\n  border-radius: var(--an-r-md);\n  overflow: hidden;\n  width: fit-content;\n  background: rgba(255, 255, 255, .02);\n  max-width: 100%;\n}\n.own-ai-navigator .an-tab {\n  font-family: var(--an-data); font-size: 11px; letter-spacing: 1px;\n  text-transform: uppercase;\n  padding: 9px 18px;\n  background: transparent; border: 0; border-right: 1px solid var(--an-border);\n  color: var(--an-text-1); cursor: pointer; font-weight: 500;\n  transition: background .12s, color .12s;\n  white-space: nowrap;\n  text-decoration: none; display: inline-flex; align-items: center;\n}\n.own-ai-navigator .an-tab:last-child { border-right: 0; }\n.own-ai-navigator .an-tab.on { background: var(--an-lime); color: var(--an-text-dark); font-weight: 700; }\n\n/* ── Panels (stacked sections; the nav scroll-spies them) ───────────────────── */\n.own-ai-navigator .an-panel { display: flex; flex-direction: column; gap: 18px; scroll-margin-top: 150px; }\n\n/* ── Section heads ──────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-section-head { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }\n.own-ai-navigator .an-eyebrow {\n  font-family: var(--an-data); font-size: 11px; font-weight: 700;\n  letter-spacing: 2.2px; text-transform: uppercase; color: var(--an-lime);\n}\n.own-ai-navigator .an-section-title { margin: 0; font-size: 20px; font-weight: 600; letter-spacing: -.01em; color: var(--an-text-0); }\n\n/* ── Trend chart ────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-chart { width: 100%; height: auto; display: block; margin: 14px 0 6px; }\n.own-ai-navigator .an-chart-x {\n  display: flex; justify-content: space-between;\n  font-family: var(--an-data); font-size: 9.5px; letter-spacing: .1em; color: var(--an-text-2);\n}\n\n/* ── KPI rail ───────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-kpi-rail {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 12px;\n}\n.own-ai-navigator .an-kpi-compact {\n  background: var(--an-card);\n  border: 1px solid var(--an-border);\n  border-radius: var(--an-r-lg);\n  padding: 16px;\n  box-shadow: 0 8px 22px rgba(0, 0, 0, .16);\n  display: flex; flex-direction: column; gap: 6px;\n  min-width: 0;\n}\n.own-ai-navigator .an-kpi-label {\n  font-family: var(--an-data); font-size: 9.5px; letter-spacing: 1.3px;\n  color: var(--an-text-2); text-transform: uppercase;\n}\n.own-ai-navigator .an-kpi-value {\n  font-family: var(--an-data); font-size: 30px; font-weight: 700;\n  line-height: 1.05; color: var(--an-text-0); font-variant-numeric: tabular-nums;\n}\n.own-ai-navigator .an-kpi-of { font-size: 15px; color: var(--an-text-2); }\n.own-ai-navigator .an-kpi-sub {\n  font-family: var(--an-data); font-size: 10px; color: var(--an-text-2);\n  display: flex; align-items: center; gap: 6px;\n}\n.own-ai-navigator .an-tone-warn .an-kpi-value { color: var(--an-amber); }\n.own-ai-navigator .an-delta.up { color: var(--an-lime); }\n\n.own-ai-navigator .an-status-dot {\n  width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex: none;\n}\n.own-ai-navigator .an-status-dot.ok { background: var(--an-green); }\n.own-ai-navigator .an-status-dot.warn { background: var(--an-amber); }\n.own-ai-navigator .an-status-dot.crit { background: var(--an-red); box-shadow: 0 0 8px rgba(255, 77, 94, .6); }\n.own-ai-navigator .an-status-dot.mute { background: var(--an-text-2); }\n\n/* ── Cards ──────────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-grid-2 { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(260px, 1fr); gap: 14px; }\n.own-ai-navigator .an-stack { display: flex; flex-direction: column; gap: 14px; min-width: 0; }\n\n.own-ai-navigator .an-focus-card {\n  background: var(--an-card);\n  border: 1px solid var(--an-border);\n  border-radius: var(--an-r-lg);\n  padding: 16px 18px;\n  box-shadow: 0 8px 22px rgba(0, 0, 0, .16);\n  min-width: 0;\n}\n.own-ai-navigator .an-card-head {\n  font-family: var(--an-data); font-size: 10px; font-weight: 600;\n  letter-spacing: 1.5px; text-transform: uppercase; color: var(--an-text-2);\n  padding-left: 8px; border-left: 2px solid var(--an-lime);\n}\n.own-ai-navigator .an-card-head-row {\n  display: flex; align-items: baseline; justify-content: space-between; gap: 12px;\n  margin-bottom: 10px;\n}\n\n/* ── Briefing card (crawling conic lime ring on hover) ──────────────────────── */\n.own-ai-navigator .an-briefing-card {\n  position: relative;\n  isolation: isolate;\n  transition: transform 280ms cubic-bezier(.22, 1, .36, 1), box-shadow 280ms cubic-bezier(.22, 1, .36, 1);\n}\n.own-ai-navigator .an-briefing-card::before {\n  content: \"\";\n  position: absolute; inset: -1.5px;\n  border-radius: inherit;\n  padding: 1.5px;\n  background: conic-gradient(from var(--an-brief-angle, 0deg), transparent 0deg, transparent 200deg, var(--an-lime) 270deg, var(--an-lime-2) 300deg, transparent 360deg);\n  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);\n  -webkit-mask-composite: xor;\n  mask-composite: exclude;\n  opacity: 0; transition: opacity 220ms ease-out; pointer-events: none; z-index: -1;\n}\n.own-ai-navigator .an-briefing-card:hover {\n  transform: translateY(-1px);\n  box-shadow: 0 18px 40px -20px rgba(0, 0, 0, .55), 0 0 0 1px rgba(212, 255, 0, .08), 0 0 32px var(--an-lime-glow);\n}\n.own-ai-navigator .an-briefing-card:hover::before { opacity: 1; animation: an-brief-crawl 3.6s linear infinite; }\n\n.own-ai-navigator .an-brief-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; }\n.own-ai-navigator .an-brief-title { margin: 0 0 8px; font-size: 20px; font-weight: 600; letter-spacing: -.01em; color: var(--an-text-0); }\n.own-ai-navigator .an-brief-body { margin: 0; font-size: 14px; line-height: 1.5; color: var(--an-text-1); }\n.own-ai-navigator .an-brief-body strong { color: var(--an-amber); font-weight: 600; }\n.own-ai-navigator .an-brief-body em { color: var(--an-info); font-style: italic; background: rgba(79, 195, 247, .06); padding: 0 3px; border-radius: 3px; }\n.own-ai-navigator .an-brief-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }\n\n/* ── Session / parked rows ──────────────────────────────────────────────────── */\n.own-ai-navigator .an-session-row {\n  display: flex; align-items: center; justify-content: space-between; gap: 10px;\n  font-size: 12.5px; color: var(--an-text-0); margin-bottom: 8px;\n}\n.own-ai-navigator .an-session-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.own-ai-navigator .an-parked-row {\n  display: flex; align-items: center; justify-content: space-between; gap: 10px;\n  font-size: 12.5px; color: var(--an-text-0); padding: 4px 0;\n}\n.own-ai-navigator .an-parked-row span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n\n/* ── Alert cards ────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-alert-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }\n.own-ai-navigator .an-alert-card {\n  border-radius: var(--an-r-lg); padding: 16px;\n  border-left: 2px solid var(--an-text-2);\n}\n.own-ai-navigator .an-alert-card.ok { background: var(--an-ok-tint); border-left-color: var(--an-green); }\n.own-ai-navigator .an-alert-card.warn { background: var(--an-warn-tint); border-left-color: var(--an-amber); }\n.own-ai-navigator .an-alert-card.crit { background: var(--an-crit-tint); border-left-color: var(--an-red); }\n.own-ai-navigator .an-alert-title {\n  display: flex; align-items: center; gap: 7px;\n  font-family: var(--an-data); font-size: 10px; font-weight: 600;\n  letter-spacing: 1.2px; text-transform: uppercase; margin-bottom: 8px;\n}\n.own-ai-navigator .an-alert-card.ok .an-alert-title { color: var(--an-green); }\n.own-ai-navigator .an-alert-card.warn .an-alert-title { color: var(--an-amber); }\n.own-ai-navigator .an-alert-card.crit .an-alert-title { color: var(--an-red); }\n.own-ai-navigator .an-alert-card p { margin: 0; font-size: 13px; line-height: 1.5; color: var(--an-text-1); }\n\n/* ── Tables ─────────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-table-wrap { overflow-x: auto; margin-top: 4px; }\n.own-ai-navigator .an-table { width: 100%; border-collapse: collapse; font-size: 12.5px; min-width: 520px; }\n.own-ai-navigator .an-table th {\n  text-align: left; font-family: var(--an-data); font-size: 9.5px; font-weight: 600;\n  letter-spacing: .12em; text-transform: uppercase; color: var(--an-text-2);\n  padding: 0 12px 8px 0; border-bottom: 1px solid var(--an-border);\n}\n.own-ai-navigator .an-table th.an-num { text-align: right; }\n.own-ai-navigator .an-table td {\n  padding: 9px 12px 9px 0; border-bottom: 1px solid var(--an-border);\n  color: var(--an-text-0); vertical-align: middle;\n}\n.own-ai-navigator .an-table tbody tr:hover td { background: rgba(255, 255, 255, .02); }\n\n/* ── Bars (regions) ──────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-bars { display: flex; flex-direction: column; gap: 10px; margin-top: 12px; }\n.own-ai-navigator .an-bar-row { display: grid; grid-template-columns: 92px 1fr 34px; align-items: center; gap: 10px; }\n.own-ai-navigator .an-bar-name { font-family: var(--an-data); font-size: 10.5px; color: var(--an-text-1); }\n.own-ai-navigator .an-bar { height: 8px; border-radius: 999px; background: var(--an-bg-0); border: 1px solid var(--an-border); overflow: hidden; }\n.own-ai-navigator .an-bar i { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--an-lime), #7FB000); box-shadow: 0 0 12px var(--an-lime-glow); transition: width .9s cubic-bezier(.22, 1, .36, 1); }\n.own-ai-navigator .an-bar i.down { background: linear-gradient(90deg, var(--an-red), #B0353F); box-shadow: none; }\n.own-ai-navigator .an-bar-val { font-family: var(--an-data); font-size: 11px; color: var(--an-text-1); text-align: right; }\n\n.own-ai-navigator .an-hero-kpi {\n  background: var(--an-bg-0);\n  border-radius: var(--an-r-lg);\n  padding: 18px;\n  margin: 6px 0 14px;\n  box-shadow: inset 0 2px 8px rgba(0, 0, 0, .5), inset 0 0 0 1px rgba(0, 0, 0, .25);\n}\n.own-ai-navigator .an-hero-val { color: var(--an-lime); text-shadow: 0 0 24px var(--an-lime-glow); }\n.own-ai-navigator .an-mini-list { display: flex; flex-direction: column; gap: 9px; }\n.own-ai-navigator .an-mini-list > div { display: flex; align-items: center; gap: 9px; font-size: 12.5px; color: var(--an-text-1); }\n.own-ai-navigator .an-mini-list > div > span:nth-child(2) { flex: 1; }\n\n/* ── Pricing tiers ───────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-tier-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-top: 6px; }\n.own-ai-navigator .an-tier {\n  position: relative;\n  background: var(--an-bg-1);\n  border: 1px solid var(--an-border);\n  border-radius: var(--an-r-lg);\n  padding: 18px;\n}\n.own-ai-navigator .an-tier-hot { border-color: var(--an-border-hot); box-shadow: 0 0 24px var(--an-lime-glow); }\n.own-ai-navigator .an-tier-badge {\n  position: absolute; top: -10px; right: 14px;\n  font-family: var(--an-data); font-size: 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;\n  background: var(--an-lime); color: var(--an-text-dark);\n  padding: 3px 8px; border-radius: 999px;\n}\n.own-ai-navigator .an-tier-name { font-family: var(--an-data); font-size: 10px; letter-spacing: 1.4px; text-transform: uppercase; color: var(--an-text-2); }\n.own-ai-navigator .an-tier-price { font-family: var(--an-data); font-size: 28px; font-weight: 700; color: var(--an-text-0); margin: 8px 0 12px; }\n.own-ai-navigator .an-tier-unit { font-size: 12px; color: var(--an-text-2); font-weight: 400; }\n.own-ai-navigator .an-tier-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 7px; }\n.own-ai-navigator .an-tier-list li { font-size: 12.5px; color: var(--an-text-1); padding-left: 16px; position: relative; }\n.own-ai-navigator .an-tier-list li::before { content: \"\"; position: absolute; left: 0; top: 7px; width: 6px; height: 6px; border-radius: 50%; background: var(--an-lime); }\n\n/* ── Footer ──────────────────────────────────────────────────────────────────── */\n.own-ai-navigator .an-footer {\n  position: relative; z-index: 1;\n  max-width: 1200px; margin: 0 auto;\n  padding: 16px 36px 28px;\n  border-top: 1px solid var(--an-border);\n  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;\n  font-size: 9.5px; letter-spacing: .1em; color: var(--an-text-2);\n}\n\n/* ── Light-cosmic theme (same component classes, tokens swap) ────────────────── */\n.own-ai-navigator.an-light {\n  --an-lime: #7FB000;\n  --an-lime-2: #8FC400;\n  --an-lime-soft: rgba(127, 176, 0, .14);\n  --an-lime-glow: rgba(127, 176, 0, .28);\n  --an-bg-0: #EDF0F7;\n  --an-bg-1: #FFFFFF;\n  --an-shell: #FFFFFF;\n  --an-card: #FFFFFF;\n  --an-card-hi: #F2F5FA;\n  --an-text-0: #0B1420;\n  --an-text-1: #33404F;\n  --an-text-2: #5C6B80;\n  --an-text-dark: #FFFFFF;\n  --an-border: rgba(11, 20, 32, .12);\n  --an-border-hot: rgba(127, 176, 0, .5);\n  --an-green: #1F8A5B;\n  --an-amber: #9A6400;\n  --an-red: #C43746;\n  background: var(--an-bg-0);\n  background-image: none;\n}\n.own-ai-navigator.an-light .an-topbar { background: rgba(255, 255, 255, .92); }\n.own-ai-navigator.an-light .an-btn-primary,\n.own-ai-navigator.an-light .an-tab.on { color: #FFFFFF; }\n.own-ai-navigator.an-light .an-avatar { color: #FFFFFF; }\n.own-ai-navigator.an-light .an-tier-badge { color: #FFFFFF; }\n.own-ai-navigator.an-light .an-kpi-compact,\n.own-ai-navigator.an-light .an-focus-card { box-shadow: 0 8px 22px rgba(11, 20, 32, .08); }\n\n/* ── Motion ──────────────────────────────────────────────────────────────────── */\n@property --an-brief-angle { syntax: \"<angle>\"; initial-value: 0deg; inherits: false; }\n@keyframes an-brief-crawl { to { --an-brief-angle: 360deg; } }\n@keyframes an-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }\n@media (prefers-reduced-motion: reduce) {\n  .own-ai-navigator .an-briefing-card { transition: none; }\n  .own-ai-navigator .an-briefing-card:hover { transform: none; }\n  .own-ai-navigator .an-briefing-card:hover::before { animation: none; }\n  .own-ai-navigator .an-bar i { transition: none; }\n}\n\n/* ── Container-responsive (production ≤880 / ≤768 cut-overs) ────────────────── */\n@container frame (max-width: 1100px) {\n  .own-ai-navigator .an-search { max-width: 240px; }\n  .own-ai-navigator .an-kpi-rail { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .own-ai-navigator .an-alert-grid { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 880px) {\n  .own-ai-navigator .an-grid-2 { grid-template-columns: 1fr; }\n  .own-ai-navigator .an-tier-grid { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 768px) {\n  .own-ai-navigator .an-topbar { flex-wrap: wrap; gap: 12px; padding: 10px 16px; }\n  .own-ai-navigator .an-topnav { order: 3; width: 100%; overflow-x: auto; }\n  .own-ai-navigator .an-search { display: none; }\n  .own-ai-navigator .an-tabs { width: 100%; overflow-x: auto; }\n  .own-ai-navigator .an-main { padding: 20px 18px 32px; }\n  .own-ai-navigator .an-footer { padding: 14px 18px 24px; }\n}\n@container frame (max-width: 430px) {\n  .own-ai-navigator .an-user-info { display: none; }\n  .own-ai-navigator .an-user { padding: 4px; }\n  .own-ai-navigator .an-kpi-rail { grid-template-columns: 1fr; }\n  .own-ai-navigator .an-greeting { font-size: 23px; }\n}\n"};
/* ══ AI NAVIGATOR — ops-console behaviour for showcase.html ═══════════════
   Registers window.OWN_LAYOUTS['ai-navigator'].init(root). Reproduces the app's
   My Dashboard interactions: the tab bar (switching panels), the KPI count-up,
   the region-bar fill animation, the tooltip chips, and the light/dark theme
   toggle (token override on the root, remembered per layout). init returns a
   cleanup fn so unmounting leaves no listener, observer, rAF or timer behind. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['ai-navigator'] = {
    init: function (root) {
      var STORE = 'own-ai-navigator-theme';

      var $ = function (sel) { return root.querySelector(sel); };
      var $$ = function (sel) { return Array.prototype.slice.call(root.querySelectorAll(sel)); };

      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var observers = [];
      var rafs = [];
      var timeouts = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        var o = Object.assign({}, opt || {});
        if (signal) o.signal = signal;
        el.addEventListener(type, fn, o);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function later(fn, ms) { var id = window.setTimeout(fn, ms); timeouts.push(id); return id; }

      /* ── theme toggle ──────────────────────────────────────────────────── */
      function setTheme(light) {
        root.classList.toggle('an-light', light);
        try { localStorage.setItem(STORE, light ? 'light' : 'dark'); } catch (e) { /* ignore */ }
      }
      var saved = null;
      try { saved = localStorage.getItem(STORE); } catch (e) { /* ignore */ }
      if (saved === 'light') setTheme(true);
      on($('[data-an-theme]'), 'click', function () {
        setTheme(!root.classList.contains('an-light'));
      });

      /* ── tooltips (data-an-tip → data-tip consumed by shared CSS not present
             inside the frame, so render a tiny inline label instead) ───────── */
      $$('.an-icon[data-an-tip]').forEach(function (btn) {
        var tip = btn.getAttribute('data-an-tip');
        if (tip) btn.setAttribute('title', tip);
      });

      /* ── section nav: scroll-spy + smooth in-layout scroll ──────────────── */
      function selectTab(id) {
        $$('.an-tab').forEach(function (t) {
          var on = t.getAttribute('data-an-tab') === id;
          t.classList.toggle('on', on);
          if (on) t.setAttribute('aria-current', 'true');
          else t.removeAttribute('aria-current');
        });
        if (id === 'an-overview') runCounts();
      }
      var SECTIONS = ['an-overview', 'an-throughput', 'an-regions', 'an-pricing'];
      if (typeof IntersectionObserver !== 'undefined') {
        var io = new IntersectionObserver(function (entries) {
          if (disposed) return;
          var visible = entries.filter(function (en) { return en.isIntersecting; });
          if (!visible.length) return;
          visible.sort(function (a, b) { return a.boundingClientRect.top - b.boundingClientRect.top; });
          selectTab(visible[0].target.id);
        }, { rootMargin: '-150px 0px -65% 0px', threshold: 0 });
        SECTIONS.forEach(function (id) {
          var el = root.querySelector('#' + id);
          if (el) io.observe(el);
        });
        observers.push(io);
      }
      $$('.an-tab').forEach(function (a) {
        on(a, 'click', function (e) {
          var href = a.getAttribute('href');
          var target = href && root.querySelector(href);
          if (!target) return;
          e.preventDefault();
          target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
          selectTab(target.id);
        });
      });
      if (location.hash && SECTIONS.indexOf(location.hash.replace('#', '')) !== -1) {
        selectTab(location.hash.replace('#', ''));
      }

      /* ── KPI count-up ───────────────────────────────────────────────────── */
      function fmtFor(el, v) {
        var fmt = el.getAttribute('data-an-fmt');
        if (fmt === 'k') return Math.round(v / 1000) + 'K';
        if (fmt === 'pct') return v.toFixed(1) + '%';
        return String(Math.round(v));
      }
      function countTo(el) {
        var to = Number(el.getAttribute('data-an-count') || 0);
        if (reduced) { el.textContent = fmtFor(el, to); return; }
        var from = Number(el.dataset.v || 0), t0 = performance.now(), ms = 900;
        function step(t) {
          if (disposed) return;
          var k = Math.min(1, (t - t0) / ms), e = 1 - Math.pow(1 - k, 4);
          el.textContent = fmtFor(el, from + (to - from) * e);
          if (k < 1) raf(step); else el.dataset.v = to;
        }
        raf(step);
      }
      function runCounts() { $$('[data-an-count]').forEach(countTo); }

      /* ── region bars: animate fill in when scrolled into view ───────────── */
      function primeBars(bars) {
        Array.prototype.forEach.call(bars.querySelectorAll('.an-bar i'), function (bar) {
          if (!bar.dataset.w) bar.dataset.w = bar.style.width || '0%';
          bar.style.width = '0%';
        });
      }
      function fillBars(bars) {
        Array.prototype.forEach.call(bars.querySelectorAll('.an-bar i'), function (bar) {
          bar.style.width = bar.dataset.w || bar.style.width;
        });
      }
      var barEls = $$('.an-bars');
      if (reduced) {
        /* leave the authored widths in place */
      } else {
        barEls.forEach(primeBars);
        if (typeof IntersectionObserver !== 'undefined') {
          var bio = new IntersectionObserver(function (entries) {
            entries.forEach(function (en) {
              if (en.isIntersecting) { fillBars(en.target); bio.unobserve(en.target); }
            });
          }, { rootMargin: '0px 0px -10% 0px', threshold: 0.2 });
          barEls.forEach(function (b) { bio.observe(b); });
          observers.push(bio);
        } else {
          barEls.forEach(fillBars);
        }
      }

      /* ── boot ───────────────────────────────────────────────────────────── */
      runCounts();

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        timeouts.forEach(function (id) { clearTimeout(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
